-- ===================================================================
-- DB Normalization Checker: planted-defect test database (PostgreSQL 17.4)
-- ===================================================================
-- Load with:
--   psql -h localhost -U postgres -f scripts/testdb/postgres_planted.sql
-- Same logical schema and row-for-row identical data as mysql_planted.sql.
-- Expected verdicts: scripts/testdb/expected_verdicts.json
-- Generated by scripts/testdb/render_planted.py -- do not hand-edit.
DROP DATABASE IF EXISTS normtest;
CREATE DATABASE normtest;
\c normtest

-- t_1nf_nokey: no key at all. Rows 61..120 duplicate rows 1..60.
CREATE TABLE t_1nf_nokey (
  rec_id INT,
  cust_code INT,
  prod_code INT,
  qty INT,
  price DECIMAL(10,2),
  order_day INT,
  region VARCHAR(8),
  channel VARCHAR(8),
  flag CHAR(1),
  note_txt VARCHAR(60)
);
INSERT INTO t_1nf_nokey
SELECT
  ((((((j-1)%60)+1)*3)%50)+1),
  ((((((j-1)%60)+1)*7)%20)+1),
  ((((((j-1)%60)+1)*11)%15)+1),
  ((((((j-1)%60)+1)*13)%9)+1),
  (((((((((j-1)%60)+1)*17)%45)%45)+1)+10)+0.99),
  ((((((j-1)%60)+1)*19)%28)+1),
  CONCAT('R', ((((((j-1)%60)+1)*23)%4)+1)),
  CONCAT('CH', ((((((j-1)%60)+1)*29)%3)+1)),
  CASE WHEN ((((((j-1)%60)+1)*31)%2))=0 THEN 'Y' ELSE 'N' END,
  CONCAT('Note_', LPAD(((((((((j-1)%60)+1)*37)%71)%50)+1))::text,3,'0'))
FROM (SELECT ((s.i-1)%60)+1 AS j FROM generate_series(1,120) AS s(i)) t;

-- t_1nf_delimited: tags holds comma-separated lists in ~70% of rows.
CREATE TABLE t_1nf_delimited (
  order_id INT PRIMARY KEY,
  customer_id INT,
  tags VARCHAR(60),
  qty INT,
  order_date DATE,
  status VARCHAR(8),
  ship_city VARCHAR(12),
  flag CHAR(1),
  note_txt VARCHAR(60)
);
INSERT INTO t_1nf_delimited
SELECT
  s.i,
  (((s.i*7)%40)+1),
  CASE WHEN ((s.i*7)%10)<7 THEN CONCAT('tag', (((s.i*1)%5)+1), ',tag', ((((s.i+2)*1)%5)+1)) ELSE CONCAT('tag', (((s.i*1)%5)+1)) END,
  ((((s.i*13)%97)%5)+1),
  DATE '2024-01-05' + ((s.i*23)%79),
  CONCAT('ST_', ((((s.i*17)%89)%4)+1)),
  CONCAT('City_', LPAD((((((s.i*19)%83)%8)+1))::text,2,'0')),
  CASE WHEN ((((s.i*31)%67)%2))=0 THEN 'Y' ELSE 'N' END,
  CONCAT('N', ((((s.i*37)%71)%200)+1))
FROM generate_series(1,150) AS s(i);

-- t_1nf_repeating: phone1, phone2, phone3 repeating group.
CREATE TABLE t_1nf_repeating (
  cust_id INT PRIMARY KEY,
  cust_name VARCHAR(20),
  phone1 VARCHAR(16),
  phone2 VARCHAR(16),
  phone3 VARCHAR(16),
  email VARCHAR(40),
  city VARCHAR(12),
  signup_date DATE,
  status VARCHAR(8),
  note_txt VARCHAR(60)
);
INSERT INTO t_1nf_repeating
SELECT
  s.i,
  CONCAT('Cust_', LPAD((s.i)::text,4,'0')),
  CONCAT('555-01', LPAD(((((s.i*1)%50)+1))::text,2,'0')),
  CONCAT('555-02', LPAD(((((s.i*7)%50)+1))::text,2,'0')),
  CONCAT('555-03', LPAD(((((s.i*11)%50)+1))::text,2,'0')),
  CONCAT('cust', s.i, '@example.com'),
  CONCAT('City_', LPAD((((((s.i*19)%83)%8)+1))::text,2,'0')),
  DATE '2023-06-01' + ((s.i*23)%79),
  CONCAT('ST_', ((((s.i*17)%89)%4)+1)),
  CONCAT('N', ((((s.i*37)%71)%200)+1))
FROM generate_series(1,150) AS s(i);

-- t_2nf_partial: PK (order_id, product_id); product_name/unit_price <- product_id; order_date <- order_id.
CREATE TABLE t_2nf_partial (
  order_id INT,
  product_id INT,
  product_name VARCHAR(20),
  unit_price DECIMAL(10,2),
  qty INT,
  order_date DATE,
  ship_mode VARCHAR(8),
  warehouse VARCHAR(8),
  priority VARCHAR(8),
  note_txt VARCHAR(60),
  PRIMARY KEY (order_id, product_id)
);
INSERT INTO t_2nf_partial
SELECT
  (((s.i*7)%60)+1),
  (((s.i*11)%50)+1),
  CONCAT('Product_', LPAD(((((s.i*11)%50)+1))::text,3,'0')),
  (((((((s.i*11)%50)+1)*13)%400)/100.0)+5),
  ((((s.i*13)%97)%5)+1),
  DATE '2024-02-01' + (((((s.i*7)%60)+1)*3)%28),
  CONCAT('SM_', ((((s.i*19)%83)%4)+1)),
  CONCAT('WH_', ((((s.i*23)%79)%6)+1)),
  CASE WHEN ((((s.i*29)%73)%2))=0 THEN 'HIGH' ELSE 'LOW' END,
  CONCAT('N', ((((s.i*31)%67)%200)+1))
FROM generate_series(1,300) AS s(i);

-- t_partial_key3: PK (a,b,c); d depends on (a,b) only.
CREATE TABLE t_partial_key3 (
  a INT,
  b INT,
  c INT,
  d VARCHAR(16),
  e INT,
  f_qty INT,
  f_status VARCHAR(8),
  f_city VARCHAR(12),
  f_flag CHAR(1),
  note_txt VARCHAR(60),
  PRIMARY KEY (a, b, c)
);
INSERT INTO t_partial_key3
SELECT
  (((s.i-1)/20)+1),
  ((((s.i-1)%20)/4)+1),
  (((s.i-1)%4)+1),
  CONCAT('AB_', (((s.i-1)/20)+1), '_', ((((s.i-1)%20)/4)+1)),
  ((((s.i*13)%97)%90)+1),
  ((((s.i*17)%89)%5)+1),
  CONCAT('ST_', ((((s.i*19)%83)%4)+1)),
  CONCAT('City_', LPAD((((((s.i*23)%79)%8)+1))::text,2,'0')),
  CASE WHEN ((((s.i*29)%73)%2))=0 THEN 'Y' ELSE 'N' END,
  CONCAT('N', ((((s.i*31)%67)%200)+1))
FROM generate_series(1,200) AS s(i);

