-- t_bcnf_only: teacher->subject (2 teachers/subject); 3NF but not BCNF.
CREATE TABLE t_bcnf_only (
  student_id INT,
  subject_code INT,
  teacher_name VARCHAR(12),
  grade CHAR(1),
  semester VARCHAR(8),
  note_txt VARCHAR(60),
  PRIMARY KEY (student_id, subject_code)
);
INSERT INTO t_bcnf_only
SELECT
  (((s.i-1)/3)+1),
  (((s.i-1)%3)+1),
  CONCAT('T', LPAD(((((((s.i-1)%3)+1)*2)-(s.i%2)))::text,2,'0')),
  CASE ((((s.i*13)%97))%4) WHEN 0 THEN 'A' WHEN 1 THEN 'B' WHEN 2 THEN 'C' ELSE 'D' END,
  CONCAT('SEM_', ((((s.i*17)%89)%4)+1)),
  CONCAT('N', ((((s.i*19)%83)%200)+1))
FROM generate_series(1,210) AS s(i);

