SELECT
  (((s.i-1)/20)+1),
  (((s.i-1)%20)+1),
  CONCAT('C_', (((s.i-1)/20)+1), '_', (((s.i-1)%20)+1)),
  CONCAT('D_', (((s.i-1)%20)+1), '_', (((s.i-1)/20)+1)),
