-- d_unique_everything: every value unique.
CREATE TABLE d_unique_everything (
  id INT PRIMARY KEY,
  u1 INT,
  u2 INT,
  code VARCHAR(12),
  email VARCHAR(40),
  token CHAR(32),
  note_txt VARCHAR(20),
  flag CHAR(1)
);
INSERT INTO d_unique_everything
SELECT
  s.i,
  (s.i+100000),
  (200000-s.i),
  CONCAT('U-', LPAD(((s.i+5000))::text,6,'0')),
  CONCAT('user', s.i, '@example.com'),
  md5((s.i)::text),
  CONCAT('N', s.i),
  CASE WHEN s.i%2=1 THEN 'Y' ELSE 'N' END
FROM generate_series(1,50) AS s(i);

