CREATE TABLE d_coincidence (
  id INT PRIMARY KEY,
  cat_a VARCHAR(8),
  cat_b VARCHAR(8),
  cat_c VARCHAR(8),
  cat_d VARCHAR(8),
  cat_e VARCHAR(8),
  cat_f VARCHAR(8),
  cat_g VARCHAR(8),
  qty INT,
  note_txt VARCHAR(60)
);
INSERT INTO d_coincidence
SELECT
  s.i,
  CONCAT('A', ((((s.i*7)%97)%9)+1)),
  CONCAT('B', ((((s.i*11)%89)%7)+1)),
  CONCAT('C', ((((s.i*13)%83)%11)+1)),
  CONCAT('D', ((((s.i*17)%79)%13)+1)),
  CASE WHEN (((s.i*19)%73)%73)<55 THEN 'E1' ELSE CASE WHEN (((s.i*19)%73)%73)<68 THEN 'E2' ELSE 'E3' END END,
  CASE WHEN (((s.i*23)%71)%71)<60 THEN 'F1' ELSE 'F2' END,
  CONCAT('G', ((((s.i*29)%67)%5)+1)),
  ((((s.i*31)%61)%5)+1),
  CONCAT('N', ((((s.i*37)%59)%200)+1))
FROM generate_series(1,100) AS s(i);

