);
INSERT INTO d_nulls
SELECT
  s.i,
  CASE WHEN (s.i%10)<3 THEN NULL ELSE CONCAT('A', (((s.i*7)%40)+1)) END,
  CASE WHEN (s.i%10)<4 THEN NULL ELSE CONCAT('B', (((s.i*11)%35)+1)) END,
  CASE WHEN (s.i%10)<2 THEN NULL ELSE CONCAT('C', (((s.i*13)%28)+1)) END,
  CASE WHEN (s.i%10)<3 THEN NULL ELSE (((s.i*17)%89)+1) END,
  CASE WHEN (s.i%10)<5 THEN NULL ELSE CONCAT('N', ((((s.i*19)%83)%200)+1)) END,
  CASE WHEN ((((s.i*23)%79)%2))=0 THEN 'Y' ELSE 'N' END,
  ((((s.i*29)%73)%5)+1)
FROM generate_series(1,150) AS s(i);

-- d_near_fd: dept_id->dept_name with 2 dirty rows (1%).
CREATE TABLE d_near_fd (
  id INT PRIMARY KEY,
  dept_id INT,
  dept_name VARCHAR(20),
  hire_date DATE,
  salary INT,
  city VARCHAR(12),
  status VARCHAR(8),
  note_txt VARCHAR(60)
);
INSERT INTO d_near_fd
SELECT
  s.i,
  (((s.i*7)%25)+1),
  CASE WHEN s.i IN (40,121) THEN 'Dept_XX_WRONG' ELSE CONCAT('Dept_', LPAD(((((s.i*7)%25)+1))::text,2,'0')) END,
  DATE '2021-01-01' + ((s.i*23)%79),
  ((((((s.i*29)%73)%50)+1)+30)*1000),
  CONCAT('City_', LPAD((((((s.i*19)%83)%8)+1))::text,2,'0')),
  CONCAT('ST_', ((((s.i*17)%89)%4)+1)),
  CONCAT('N', ((((s.i*31)%67)%200)+1))
FROM generate_series(1,200) AS s(i);

-- d_dirty_pairs: every group has 2 disagreeing rows.
CREATE TABLE d_dirty_pairs (
  id INT PRIMARY KEY,
  pair_id INT,
  side VARCHAR(8),
  note_txt VARCHAR(60),
  flag CHAR(1),
  amt INT
);
INSERT INTO d_dirty_pairs
SELECT
  s.i,
  (((s.i-1)/2)+1),
  CASE WHEN s.i%2=1 THEN 'LEFT' ELSE 'RIGHT' END,
  CONCAT('N', ((((s.i*13)%97)%200)+1)),
  CASE WHEN ((((s.i*17)%89)%2))=0 THEN 'Y' ELSE 'N' END,
  ((((s.i*19)%83)%500)+1)
FROM generate_series(1,120) AS s(i);

-- d_equiv_cols: 10-row lookup; code <-> country 1-1.
CREATE TABLE d_equiv_cols (
  code VARCHAR(8) PRIMARY KEY,
  country VARCHAR(20),
  capital VARCHAR(20),
  currency VARCHAR(12),
  note_txt VARCHAR(60)
);
INSERT INTO d_equiv_cols
SELECT
  CONCAT('CC', LPAD((s.i)::text,2,'0')),
  CONCAT('Country_CC', LPAD((s.i)::text,2,'0')),
  CONCAT('Capital_CC', LPAD((s.i)::text,2,'0')),
  CONCAT('Cur_CC', LPAD((s.i)::text,2,'0')),
  CONCAT('N', s.i)
FROM generate_series(1,10) AS s(i);

-- d_wide_text: LOB/JSON excluded from FD search.
CREATE TABLE d_wide_text (
  id INT PRIMARY KEY,
  title VARCHAR(120),
  body TEXT,
  attachment BYTEA,
  meta JSON,
  created_date DATE,
  author VARCHAR(20)
);
INSERT INTO d_wide_text
SELECT
  s.i,
  CONCAT('Doc_', LPAD((s.i)::text,4,'0'), '_', 'xxxxxxxxxxxxxxxxxxxx'),
  repeat(CONCAT('lorem-', ((s.i*1)%7), ' '), 30),
  convert_to(repeat(CONCAT('bin-', ((s.i*1)%5), ';'), 40), 'UTF8'),
  (CONCAT('{"k": ', ((s.i*1)%5), '}'))::json,
  DATE '2023-01-01' + ((s.i*23)%79),
  CONCAT('Author_', ((((s.i*29)%73)%10)+1))
FROM generate_series(1,80) AS s(i);

