  (((s.i*7)%100)+1),
  CONCAT('Customer_', LPAD(((((s.i*7)%100)+1))::text,3,'0')),
  DATE '2024-01-05' + ((s.i*23)%79),
  ((((s.i*13)%97)%5)+1),
  ((((((s.i*29)%73)%40)+1)+10)+0.99),
  CONCAT('ST_', ((((s.i*17)%89)%4)+1)),
